"""Build maximal-ish requests and time the candidate."""
import json, sys, time, subprocess

def torus3d_session(n=7, scope='host', ntasks=100000, ngroups=64, ntx=1000, nedit=3):
    N = n ** 3
    templates = N * (N - 1)
    # template index for (s,d): sum over s'<s of (N-1) + (d - (d>s))
    def tidx(s, d):
        return s * (N - 1) + (d if d < s else d - 1)
    groups = [[1, 10 ** 12] for _ in range(ngroups)]
    tasks = []
    for t in range(ntasks):
        g = t % ngroups
        s = g % N
        d = (s + 1 + (t // N) % (N - 1)) % N
        if d == s: d = (d + 1) % N
        tasks.append([tidx(s, d), g, 1, 0, 0])
    # compute usage
    import collections
    usage = [0] * N
    # approximate: use reference to compute exact usage
    sys.path.insert(0, '/workspace/tmp')
    import reference
    topo = reference.Topology(['torus3d', n, scope])
    state = reference.State(topo, [0] * N, groups, tasks)
    use = state.usage()
    caps = [u + 1 for u in use]
    txs = []
    for i in range(ntx):
        edits = []
        for j in range(nedit):
            t = (i * nedit + j) % ntasks
            edits.append(['weight', t, 1 + j])
        txs.append({'revision': i, 'edits': edits,
                    'query': {'groups': [0], 'nodes': [0, 1], 'tasks': [0, 1]}})
    return {'topology': ['torus3d', n, scope], 'caps': caps, 'groups': groups, 'tasks': tasks,
            'query': {'groups': list(range(min(ngroups, 8))), 'nodes': list(range(8)), 'tasks': list(range(8))},
            'transactions': txs}

def main():
    which = sys.argv[1]
    if which == 'topo':
        req = {'version': 2, 'sessions': [torus3d_session(ntasks=0, ngroups=1, ntx=0, nedit=0) for _ in range(3)]}
    elif which == 'tasks':
        req = {'version': 2, 'sessions': [torus3d_session(ntasks=100000, ngroups=64, ntx=100, nedit=3)]}
    elif which == 'tx':
        req = {'version': 2, 'sessions': [torus3d_session(ntasks=1000, ngroups=64, ntx=50000, nedit=2)]}
    elif which == 'many':
        req = {'version': 2, 'sessions': [torus3d_session(ntasks=20000, ngroups=8192, ntx=10000, nedit=5) for _ in range(3)]}
    data = json.dumps(req, separators=(',', ':'))
    print('input bytes', len(data))
    start = time.time()
    proc = subprocess.run([sys.executable, '-B', '/workspace/submission/main.py'], input=data.encode(),
                          stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=180)
    elapsed = time.time() - start
    print('elapsed %.1fs rc=%d out=%d' % (elapsed, proc.returncode, len(proc.stdout)))
    if proc.returncode != 0: print(proc.stderr.decode()[:3000])
    else: print(proc.stdout[:200])

main()
